        if not (0<=r<m and 0<=c<n) or (r,c) in seen or board[r][c] not in node: return
        node=node[board[r][c]]
        if '$' in node: found.add(node['$'])
        seen.add((r,c))
        for x,y in ((r+1,c),(r-1,c),(r,c+1),(r,c-1)): dfs(x,y,node)
        seen.remove((r,c))
    for r in range(m):
        for c in range(n): dfs(r,c,root)
    return sorted(found)

def solve(nums, k):
    import heapq
    from collections import Counter
    counts=Counter(nums)
    return heapq.nsmallest(k,counts,key=lambda n:(-counts[n],n))

def solve(nums):
    import heapq
    lower=[]; upper=[]; result=[]
    for n in nums:
        heapq.heappush(lower,-n)
        heapq.heappush(upper,-heapq.heappop(lower))
        if len(upper)>len(lower): heapq.heappush(lower,-heapq.heappop(upper))
        result.append(-lower[0] if len(lower)>len(upper) else (-lower[0]+upper[0])/2)
    return result
